void send_scsi_event(struct vhost_scsi *vs, struct vhost_scsi_tpg *tpg,
                     struct se_lun *lun, u32 event, u32 reason)
{
    struct scsi_event *se;

    se = kzalloc(sizeof(*se), GFP_KERNEL);
    if (!se)
        return;

    se->event = event;
    se->reason = reason;

    if (tpg)
        memcpy(&se->tpg, tpg, sizeof(se->tpg));
    else
        memset(&se->tpg, 0, sizeof(se->tpg));

    if (lun)
        memcpy(&se->lun, lun, sizeof(se->lun));
    else
        memset(&se->lun, 0, sizeof(se->lun));

    list_add_tail(&se->list, &vs->event_list);
    queue_work(vs->event_wq, &vs->event_work);
}

void vhost_scsi_send_event(struct vhost_scsi *vs, struct vhost_scsi_tpg *tpg,
                           struct se_lun *lun, u32 event, u32 reason)
{
    struct vhost_scsi_event *ev;

    ev = kzalloc(sizeof(*ev), GFP_KERNEL);
    if (!ev)
        return;

    ev->event = event;
    ev->reason = reason;

    if (tpg) {
        ev->tpg_id = tpg->tpg_id;
        memcpy(ev->tpg_guid, tpg->tpg_guid, VHOST_SCSI_TPGUID_LEN);
    }

    if (lun) {
        ev->lun = lun->lun;
        ev->lun_mapped_lun = lun->mapped_lun;
    }

    ev->vs = vs;
    spin_lock(&vs->event_lock);
    list_add_tail(&ev->list, &vs->event_list);
    spin_unlock(&vs->event_lock);

    queue_work(vs->event_wq, &vs->event_work);
}

